class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        rows, cols = len(board), len(board[0])
        cells = [(r, c) for r in range(rows) for c in range(cols)]
        last = len(word) - 1

        def neighbors(r: int, c: int):
            return [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]

        # Guard table: can[i] holds the cells that could spell word[i:]
        # if a path were allowed to reuse cells. It is the DFS below
        # without the used set, filled from the last letter to the first.
        can = [set() for _ in word]
        for i in range(last, -1, -1):
            for r, c in cells:
                if board[r][c] == word[i] and (
                    i == last or any(nb in can[i + 1] for nb in neighbors(r, c))
                ):
                    can[i].add((r, c))

        used = set()  # cells on the current path

        def dfs(r: int, c: int, i: int) -> bool:
            # can[i] holds only in-bounds cells that match word[i],
            # so this one test checks bounds, letter and future.
            if (r, c) not in can[i] or (r, c) in used:
                return False
            if i == last:
                return True
            used.add((r, c))
            found = any(dfs(nr, nc, i + 1) for nr, nc in neighbors(r, c))
            used.remove((r, c))
            return found

        return any(dfs(r, c, 0) for r, c in cells)

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        n = len(heights)

        def nearest_smaller(order, default):
            # For each i, the index of the closest strictly shorter bar seen before i in this order.
            result = [default] * n
            stack = []  # indices; heights strictly increase from bottom to top
            for i in order:
                while stack and heights[stack[-1]] >= heights[i]:
                    stack.pop()
                if stack:
                    result[i] = stack[-1]
                stack.append(i)
            return result

        left = nearest_smaller(range(n), -1)
        right = nearest_smaller(range(n - 1, -1, -1), n)

        best = 0
        for i in range(n):
            width = right[i] - left[i] - 1
            best = max(best, heights[i] * width)
        return best

from collections import Counter
from typing import List


class Solution:
    def subsetsWithDup(self, nums: List[int]) -> List[List[int]]:
        res = [[]]                                   # the empty subset
        for value, count in sorted(Counter(nums).items()):
            # every old subset takes 0, 1, ..., count copies of value
            res = [subset + [value] * k for subset in res for k in range(count + 1)]
        return res

from functools import lru_cache


class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        if len(s1) + len(s2) != len(s3):
            return False

        @lru_cache(maxsize=None)
        def can(i, j):
            # Can s1[i:] and s2[j:] interleave to form s3[i + j:]?
            if i == len(s1) and j == len(s2):
                return True
            k = i + j  # next character of s3 to match
            if i < len(s1) and s1[i] == s3[k] and can(i + 1, j):
                return True
            if j < len(s2) and s2[j] == s3[k] and can(i, j + 1):
                return True
            return False

        return can(0, 0)

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        # Each entry carries the open interval (low, high) that the node value must fit in.
        stack = [(root, float("-inf"), float("inf"))]
        while stack:
            node, low, high = stack.pop()
            if not node:
                continue
            if not (low < node.val < high):
                return False
            stack.append((node.left, low, node.val))   # left side: new upper bound
            stack.append((node.right, node.val, high))  # right side: new lower bound
        return True

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        if not p and not q:
            return True
        if not p or not q or p.val != q.val:
            return False
        return self.isSameTree(p.left, q.left) and self.isSameTree(p.right, q.right)

from typing import List, Optional


# Definition for a binary tree node (provided by LeetCode).
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right


class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        res = []
        level = [root]
        while level:
            res.append([node.val for node in level])
            next_level = []
            for node in level:
                if node.left:
                    next_level.append(node.left)
                if node.right:
                    next_level.append(node.right)
            level = next_level
        return res

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def maxDepth(self, root: Optional[TreeNode]) -> int:
        depth = 0
        level = [root] if root else []
        while level:
            depth += 1
            next_level = []
            for node in level:
                if node.left:
                    next_level.append(node.left)
                if node.right:
                    next_level.append(node.right)
            level = next_level
        return depth

class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        m, n = len(s), len(t)
        # dp[i][j] = number of ways to form t[:j] from s[:i]
        dp = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            dp[i][0] = 1  # empty t: choose nothing, one way
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                dp[i][j] = dp[i - 1][j]  # skip s[i-1]
                if s[i - 1] == t[j - 1]:
                    dp[i][j] += dp[i - 1][j - 1]  # use s[i-1] as t[j-1]
        return dp[m][n]

from typing import List


class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        min_price = prices[0]  # cheapest buy price seen so far
        best = 0               # best profit so far; 0 means "do not trade"
        for price in prices:
            min_price = min(min_price, price)       # buy at the lowest price so far
            best = max(best, price - min_price)     # sell today, keep the best
        return best

class Solution:
    def isPalindrome(self, s: str) -> bool:
        cleaned = [ch.lower() for ch in s if ch.isalnum()]
        return cleaned == cleaned[::-1]

