class Solution:
    def validTree(self, n: int, edges: List[List[int]]) -> bool:
        # A tree on n nodes has exactly n - 1 edges.
        if len(edges) != n - 1:
            return False

        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        # With n - 1 edges, connected implies acyclic.
        seen = {0}
        stack = [0]
        while stack:
            node = stack.pop()
            for nei in adj[node]:
                if nei not in seen:
                    seen.add(nei)
                    stack.append(nei)
        return len(seen) == n

