class KthLargest:

    def __init__(self, k: int, nums: List[int]):
        self.k = k
        self.top_k = []  # min-heap that keeps the k largest values seen so far
        for num in nums:
            self.add(num)  # every value goes through the same gate

    def add(self, val: int) -> int:
        heapq.heappush(self.top_k, val)
        if len(self.top_k) > self.k:
            heapq.heappop(self.top_k)  # drop the weakest, it can never be the answer again
        return self.top_k[0]  # the smallest of the top k is the kth largest

class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        answer = [0] * len(temperatures)
        waiting = []  # indices of days that still wait for a warmer day
        for today, temp in enumerate(temperatures):
            # today resolves every waiting day that is strictly colder
            while waiting and temperatures[waiting[-1]] < temp:
                day = waiting.pop()
                answer[day] = today - day
            waiting.append(today)
        return answer

